function arrange(){const order=organs.filter(o=>o.name!==erased).sort((a,b)=>a.x-b.x).map(o=>o.name.toLowerCase());$('sentence').textContent=erased?`${erased.toLowerCase()} never existed. ${order[0]} dreams ${order[1]}. ${order[2]} mistakes ${order[3]} for its missing organ.`:`${order[0]} dreams ${order[1]}. ${order[2]} eats ${order[3]}. ${order[4]} calls this a body.`;organs.forEach((o,i)=>{const b=$('organ-'+i);b.style.left=o.x*100+'%';b.style.top=o.y*100+'%';b.textContent=['⊙','⟁','∴','◇','∞'][i]+' '+o.name;b.setAttribute('aria-label',o.name+(o.name===erased?' never existed. Its ghost can still be moved.':'')+'. Use arrow keys to relocate this organ.');});refreshKnots();singAnatomy(true);paint();}
