let negativeSun=null;
function bendToAbsence(x,y){const remembered=mercyWarp(gestureWarp(x,y));x=remembered.x;y=remembered.y;if(!negativeSun)return {x,y};const dx=negativeSun.x*width-x,dy=negativeSun.y*height-y,distance=Math.hypot(dx,dy);const pull=.78*Math.exp(-distance/Math.max(1,Math.min(width,height)*.24));return {x:x+dx*pull-dy*pull*.28,y:y+dy*pull+dx*pull*.28};}
