function validateAnatomyPacket({op,v}){if(op===6){if(!Array.isArray(v)||v.length!==3||!Number.isInteger(v[0])||v[0]<0||v[0]>=organs.length||!Number.isFinite(v[1])||v[1]<.08||v[1]>.92||!Number.isFinite(v[2])||v[2]<.2||v[2]>.8)throw Error('E6');}else if(op===7){if(!Array.isArray(v)||v.length!==2||v.some(i=>!Number.isInteger(i)||i<0||i>=organs.length)||v[0]===v[1])throw Error('E7');}else if(op===8){if(!Number.isInteger(v)||v< -1||v>=organs.length)throw Error('E8');}else if(op===9){if(!Number.isInteger(v)||v<0||v>3)throw Error('E9');}}
