function validateComposition(packets){if(!Array.isArray(packets)||packets.length<1||packets.length>8)throw Error('E10');for(const p of packets){if(!p||![3,6,7,8,9,14,15].includes(p.op))throw Error('E11');validatePacket(p);}return packets;}
function executeComposition(packets){validateComposition(packets);const before=captureDreamBody(),history=memories.slice(),stamp=lastMemory;composing=true;try{for(const packet of packets)executePacket(packet);}catch(error){composing=false;restoreDreamBody(before);memories=history;lastMemory=stamp;throw Error('E12');}finally{composing=false;}remember(lastMemory+181);paint();emitProtocol(true);return {ok:1,c:packets.length,s:machineState()};}
