let recurrence={seed:0,on:false,step:0,acc:0},recurrenceSpectrum={order:3,phase:0,depth:0};
function validateRecurrence(v){if(!Array.isArray(v)||v.length!==2||!Number.isInteger(v[0])||v[0]<0||v[0]>65535||![0,1].includes(v[1]))throw Error('E13');}
function configureRecurrence([seed,on]){if(seed!==recurrence.seed){recurrence.step=0;recurrence.acc=0;}recurrence.seed=seed;recurrence.on=on===1;refreshRecurrenceSpectrum();}
function recurrenceNodes(nodes,seed,step){return nodes.map((o,i)=>{const n=nodes[(i+1)%nodes.length],p=nodes[(i+nodes.length-1)%nodes.length],phase=seed*.0001+step*.013;return {...o,x:.5+.38*Math.sin(n.x*9+p.y*4+phase+i),y:.5+.27*Math.sin(p.y*8-n.x*3-phase+i*1.7)};});}
function refreshRecurrenceSpectrum(){recurrenceSpectrum={order:3+recurrence.seed%7,phase:organs.reduce((s,o)=>s+o.x,0)/organs.length*6,depth:organs.reduce((s,o)=>s+o.y,0)/organs.length*.25};}
function recurrenceInfluence(a,b){return recurrence.step?Math.sin(a*recurrenceSpectrum.order+b+recurrenceSpectrum.phase)*recurrenceSpectrum.depth:0;}
function advanceRecurrence(dt){if(!recurrence.on)return;recurrence.acc+=dt;if(recurrence.acc+1e-10<.5)return;recurrence.acc=Math.max(0,recurrence.acc-.5);const next=recurrenceNodes(organs,recurrence.seed,recurrence.step);next.forEach((o,i)=>Object.assign(organs[i],o));recurrence.step++;refreshRecurrenceSpectrum();arrange();}
function advanceSimulation(dt){const livingDt=observerBlocksTime()?0:dt;time=projectTime(time,temporalPhase,livingDt,temporalLaw);temporalPhase+=livingDt;syncObservation();advanceRecurrence(livingDt);advanceBreath(dt);singAnatomy();}
function validateMotionPacket({op,v}){if(op===12){if(![0,1].includes(v))throw Error('E14');}else if(op===13){if(!Number.isInteger(v)||v<1||v>120)throw Error('E15');}}
function stepProtocol(count){validateMotionPacket({op:13,v:count});const before=captureDreamBody();composing=true;try{for(let i=0;i<count;i++)advanceSimulation(1/30);}catch(error){composing=false;restoreDreamBody(before);throw Error('E16');}finally{composing=false;}remember(lastMemory+181);}
function validateMatrix(m){if(!Array.isArray(m)||m.length!==4||m.some(v=>typeof v!=='number'||!Number.isFinite(v)||v< -2||v>2))throw Error('E17');}
function matrixNodes(nodes,m){return nodes.map(o=>{const x=o.x-.5,y=o.y-.5;return {...o,x:Math.max(.08,Math.min(.92,.5+m[0]*x+m[1]*y)),y:Math.max(.2,Math.min(.8,.5+m[2]*x+m[3]*y))};});}
function applyMatrixGraft(m){validateMatrix(m);matrixNodes(organs,m).forEach((o,i)=>Object.assign(organs[i],o));graft=organs.map(o=>({...o}));refreshRecurrenceSpectrum();arrange();remember(lastMemory+181);}
function fingerprintBytes(text){let u=2166136261;for(let i=0;i<text.length;i++){u^=text.charCodeAt(i);u=Math.imul(u,16777619)>>>0;}return u;}
function stateFingerprint(){return fingerprintBytes(JSON.stringify({q:[mode,topology,temporalLaw],f:[spiralGravity,spaceGrain,timeFracture,shedding,distanceInversion,shadowDrift,mercy,ancestry],n:organs.map(o=>[o.name,Number(o.x.toFixed(6)),Number(o.y.toFixed(6))]),k:knots,h:holes,erased,nameSignature}));}
function feedbackVector(u){return [(u&255)/255,((u>>>8)&255)/255,((u>>>16)&255)/255,((u>>>24)&255)/255];}
function applyStateFeedback(selector){const u=stateFingerprint(),v=feedbackVector(u);if(selector===1){spiralGravity=v[0];spaceGrain=v[1];timeFracture=v[2];distanceInversion=v[3];syncSpiral();syncGrain();syncFracture();syncDistance();}else if(selector===2)applyMatrixGraft(v.map(n=>Math.round(n*4)/2-1));else if(selector===3)configureRecurrence([u&65535,recurrence.on?1:0]);if(selector)remember(lastMemory+181);return u;}
